const input = $input.first().json;
const normalizePhone = (value) => '+' + String(value || '').replace(/\D/g, '');
const normalizeText = (value) => String(value || '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().trim();
const authorizedUsers = {
  '+573222046768': 'Nicol\u00e1s',
  '+573027697381': 'Santi'
};
const customerPhone = normalizePhone(input.customerPhone);
const messageText = String(input.messageText || '').trim();
const normalizedText = normalizeText(messageText);
const userName = authorizedUsers[customerPhone] || null;
const isAuthorized = Boolean(userName);
const clients = [{ clientId: 'CLI-001', clientName: 'Proyecto Pek\u00edn', aliases: ['proyecto pekin', 'proyecto kinku', 'pekin', 'kinku', '1'] }];
const selectedClient = clients.find((client) => client.aliases.some((alias) => /^\d+$/.test(alias) ? normalizedText === alias : normalizedText.includes(alias))) || null;
const divider = '\u2501'.repeat(14);
let route = 'standard_chat';
let replyText = '';
let shouldGenerateReport = false;
if (isAuthorized && selectedClient) {
  route = 'report_request';
  shouldGenerateReport = true;
  replyText = [
    '\u{1F680} *TIC TAC | INFORME EN PROCESO*',
    divider,
    `\u{1F464} *Solicitado por:* ${userName}`,
    `\u{1F3E2} *Proyecto:* ${selectedClient.clientName}`,
    '\u{1F4CA} *Estado:* Recopilando y analizando informaci\u00f3n',
    '',
    'Te avisar\u00e9 por este chat tan pronto el informe est\u00e9 listo. \u2705',
    divider,
    '_Tic Tac Agency Performance SAS_'
  ].join('\n');
} else if (isAuthorized) {
  route = 'report_menu';
  replyText = [
    '\u{1F4CA} *TIC TAC | INFORMES EJECUTIVOS*',
    divider,
    `\u00a1Hola, *${userName}*! \u{1F44B}`,
    'Selecciona el proyecto que deseas analizar:',
    '',
    '1\uFE0F\u20E3 *Proyecto Pek\u00edn*',
    '   _Tambi\u00e9n puedes escribir "Pek\u00edn" o "Kinku"._',
    '',
    '\u{1F4AC} Responde con el *n\u00famero* o el *nombre del proyecto* para comenzar.',
    divider,
    '_Tic Tac Agency Performance SAS_'
  ].join('\n');
} else {
  replyText = [
    '\u{1F44B} *TIC TAC AGENCY*',
    divider,
    '\u00a1Hola! Hemos recibido tu mensaje correctamente.',
    '',
    'Nuestro asistente est\u00e1 listo para ayudarte. \u{1F916}',
    divider,
    '_Tic Tac Agency Performance SAS_'
  ].join('\n');
}
return [{ json: { ...input, customerPhone, messageText, userName, isAuthorized, route, shouldGenerateReport, clientId: selectedClient?.clientId || null, clientName: selectedClient?.clientName || null, replyText } }];
